import{_ as t,o as s,c as a,a2 as i}from"./chunks/framework.iWwp2X7T.js";const u=JSON.parse('{"title":"Quickstart","description":"Mobile Inspector development documentation · Quickstart","frontmatter":{"title":"Quickstart","description":"Mobile Inspector development documentation · Quickstart"},"headers":[],"relativePath":"en/guide/quickstart.md","filePath":"en/guide/quickstart.md"}'),n={name:"en/guide/quickstart.md"};function r(o,e,l,h,p,c){return s(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="quickstart" tabindex="-1">Quickstart <a class="header-anchor" href="#quickstart" aria-label="Permalink to &quot;Quickstart&quot;">​</a></h1><p>A useful first run takes no phone, account or model. It starts one local viewer and lets you inspect deliberately synthetic traffic.</p><h2 id="before-you-start" tabindex="-1">Before you start <a class="header-anchor" href="#before-you-start" aria-label="Permalink to &quot;Before you start&quot;">​</a></h2><p>The product source is private. Obtain authorized repository access and select a reviewed ref first; this public documentation does not grant access. There is no public stable npm package, binary or release tag in this edition. You need Node.js 22+, Git and OpenSSL for generated local TLS.</p><h2 id="start-from-the-checkout" tabindex="-1">Start from the checkout <a class="header-anchor" href="#start-from-the-checkout" aria-label="Permalink to &quot;Start from the checkout&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ci</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --ignore-scripts</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bin/mobile-inspector.mjs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bin/mobile-inspector.mjs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> doctor</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bin/mobile-inspector.mjs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span></span></code></pre></div><p>Open the viewer URL printed by the process. Choose the labelled synthetic example. HTTP status, SSE frames and related logs should appear in the same session. Nothing here contacts a sample business endpoint or enables diagnosis.</p><h2 id="check-the-result" tabindex="-1">Check the result <a class="header-anchor" href="#check-the-result" aria-label="Permalink to &quot;Check the result&quot;">​</a></h2><p>Confirm the synthetic label, request timeline and log level. A visible page proves rendering; a received synthetic event proves only the local example. Neither proves phone pairing, business success or model interoperability. Stop your foreground process with Ctrl+C when finished.</p><p>Next, follow <a href="./../tutorials/first-capture">the first-capture tutorial</a> for project-scoped CLI evidence, or <a href="./connection-lan">LAN pairing</a> for an already integrated internal app.</p>`,10)])])}const k=t(n,[["render",r]]);export{u as __pageData,k as default};
